import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.DYAmjhAm.js";const g=JSON.parse('{"title":"Migrating from 2.x","description":"","frontmatter":{},"headers":[],"relativePath":"guide/migrating-from-2x.md","filePath":"guide/migrating-from-2x.md","lastUpdated":1789761211000}'),o={name:"guide/migrating-from-2x.md"};function n(r,e,d,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="migrating-from-2-x" tabindex="-1">Migrating from 2.x <a class="header-anchor" href="#migrating-from-2-x" aria-label="Permalink to &quot;Migrating from 2.x&quot;">​</a></h1><p>Most applications need only a handful of changes. This page lists all of them.</p><p>The canonical version of this list lives in <a href="https://github.com/Breeze/breeze-client-v3/blob/master/UPGRADE.md" target="_blank" rel="noreferrer">UPGRADE.md</a> in the repository, and is kept in step with the code.</p><h2 id="_1-install" tabindex="-1">1. Install <a class="header-anchor" href="#_1-install" aria-label="Permalink to &quot;1. Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> breeze-client</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 3.0.0</span></span></code></pre></div><p>One package, one tag. 2.x published the same package under <code>latest</code>, <code>mjs</code>, <code>cjs</code> and <code>umd</code>. If your <code>package.json</code> says <code>&quot;breeze-client&quot;: &quot;cjs&quot;</code>, change it to <code>&quot;^3.0.0&quot;</code>.</p><p><strong>ESM only.</strong> <code>require(&#39;breeze-client&#39;)</code> no longer works, there is no UMD bundle, and the <code>&lt;script src=&quot;breeze.debug.js&quot;&gt;</code> + global <code>breeze</code> style of deployment is gone. Use a bundler, or an import map. Node 20 or later.</p><p>Subpath imports are spelled the same as before:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { EntityManager } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;breeze-client&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { DataServiceWebApiAdapter } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;breeze-client/adapter-data-service-webapi&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h2 id="_2-removed-knockout-jquery-angularjs-odata" tabindex="-1">2. Removed: Knockout, jQuery, AngularJS, OData <a class="header-anchor" href="#_2-removed-knockout-jquery-angularjs-odata" aria-label="Permalink to &quot;2. Removed: Knockout, jQuery, AngularJS, OData&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Removed</th><th>What to do</th></tr></thead><tbody><tr><td><code>adapter-model-library-ko</code></td><td>Move models to the backing-store adapter (the default), or stay on 2.x</td></tr><tr><td><code>adapter-ajax-jquery</code></td><td>Remove it — Breeze 3 calls <code>fetch</code> directly</td></tr><tr><td><code>adapter-ajax-angularjs</code></td><td>AngularJS reached end of life in 2022. Stay on 2.x</td></tr><tr><td><code>adapter-data-service-odata</code></td><td>Stay on 2.x — Breeze&#39;s JSON query format is the supported path</td></tr><tr><td><code>adapter-uri-builder-odata</code></td><td>Use <code>adapter-uri-builder-json</code> with a Breeze .NET server</td></tr></tbody></table><h3 id="entities-always-have-plain-properties" tabindex="-1">Entities always have plain properties <a class="header-anchor" href="#entities-always-have-plain-properties" aria-label="Permalink to &quot;Entities always have plain properties&quot;">​</a></h3><p>The model library used to decide the shape of an entity. With Knockout gone there is only the backing store, so a property is just a property:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">order.freight;           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 2.x with Knockout: order.freight()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">order.freight </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 2.x with Knockout: order.freight(12.5)</span></span></code></pre></div><p><code>getProperty</code> and <code>setProperty</code> still work, on entities and complex objects alike. To drive a UI, bind to the plain values and use the events in <a href="/breeze-client-v3/guide/change-tracking">Change tracking</a> to find out when they change.</p><h3 id="what-else-went-with-odata" tabindex="-1">What else went with OData <a class="header-anchor" href="#what-else-went-with-odata" aria-label="Permalink to &quot;What else went with OData&quot;">​</a></h3><ul><li><strong><code>Predicate.toODataFragment</code> is gone.</strong> It was never a core method: the OData URI builder added it to <code>Predicate.prototype</code> when you imported that adapter. Use <code>toJSON()</code>.</li><li><strong>Requests no longer carry <code>$filter</code>, <code>$orderby</code>, <code>$select</code> or <code>$expand</code>.</strong> The JSON URI builder is the only one left, so if you inspect network traffic, expect Breeze&#39;s JSON query format. A server that understands only OData query syntax is not supported — stay on 2.x for those.</li></ul><h3 id="csdl-edmx-metadata-is-no-longer-parsed" tabindex="-1">CSDL / EDMX metadata is no longer parsed <a class="header-anchor" href="#csdl-edmx-metadata-is-no-longer-parsed" aria-label="Permalink to &quot;CSDL / EDMX metadata is no longer parsed&quot;">​</a></h3><p><code>MetadataStore.importMetadata()</code> used to detect a <code>schema</code> property and parse CSDL — the OData / EDMX metadata format. That is gone, along with <code>DataType.fromEdmDataType</code>. Passing CSDL to <code>importMetadata()</code> now throws a clear error rather than silently importing nothing.</p><p>This matters if you fetch metadata from an <strong>OData <code>$metadata</code> endpoint</strong> or an older Breeze <strong>WebApi2 + EF6</strong> server. Breeze .NET Core servers emit Breeze JSON metadata and are unaffected.</p><p>An object with a <code>schema</code> property and no <code>structuralTypes</code> makes <code>importMetadata()</code> throw <em>This looks like CSDL (OData / EDMX) metadata, which breeze-client 3 does not read</em>, prefixed by <em>Unable to either parse or import metadata</em>. So pointing Breeze 3 at such a server fails on the first metadata fetch with that message rather than importing nothing.</p><p>If your metadata is CSDL: move the server to Breeze .NET Core, which emits native JSON. Or, while still on 2.x, load the CSDL once, call <code>exportMetadata()</code>, and check the resulting JSON in — Breeze 3 can <a href="/breeze-client-v3/metadata/by-hand#loading-metadata-from-a-json-file">import that file</a>.</p><h3 id="the-breeze-labs-metadata-helper-is-gone" tabindex="-1">The Breeze Labs Metadata-Helper is gone <a class="header-anchor" href="#the-breeze-labs-metadata-helper-is-gone" aria-label="Permalink to &quot;The Breeze Labs Metadata-Helper is gone&quot;">​</a></h3><p>The 2.x docs used <code>breeze.metadata-helper.js</code> for hand-written metadata, with abbreviated attribute names (<code>type</code>, <code>max</code>, <code>fk</code>) and convention-based defaults. There is no v3 version. The native API is nearly as short — it takes property maps, qualifies navigation type names for you and has sensible defaults. See <a href="/breeze-client-v3/metadata/by-hand">Writing metadata by hand</a>.</p><h3 id="angular" tabindex="-1">Angular <a class="header-anchor" href="#angular" aria-label="Permalink to &quot;Angular&quot;">​</a></h3><p>There is no <code>adapter-ajax-httpclient</code> in the v3 package. Breeze 3 works in an Angular application as it is, and makes its requests with <code>fetch</code>. To keep them going through <code>HttpClient</code>, import <code>httpClientFetch</code> from <code>breeze-client/adapter-angular-httpclient</code> — an <a href="/breeze-client-v3/guide/extensions#angular-httpclient">optional extension</a> that takes the 2.x adapter&#39;s place. <a href="/breeze-client-v3/guide/angular">Angular</a> covers setting it up, change detection and auth headers.</p><h2 id="_3-importing-an-adapter-no-longer-registers-it" tabindex="-1">3. Importing an adapter no longer registers it <a class="header-anchor" href="#_3-importing-an-adapter-no-longer-registers-it" aria-label="Permalink to &quot;3. Importing an adapter no longer registers it&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 2.x: the import alone registered the adapter</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;breeze-client/adapter-data-service-webapi&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>v3 modules do not touch global state on import. For the standard adapters this does not matter, because they need no registration at all. With nothing registered, Breeze uses <code>DataServiceWebApiAdapter</code>, <code>UriBuilderJsonAdapter</code> and <code>ModelLibraryBackingStoreAdapter</code>, and sends requests through <code>fetch</code>. You can delete the side-effect imports.</p><p>2.x startup code that then initialized those adapters by name keeps working, even though nothing registered them:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">initializeAdapterInstance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;modelLibrary&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;backingStore&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">initializeAdapterInstance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;uriBuilder&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;json&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">initializeAdapterInstance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;dataService&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;webApi&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">initializeAdapterInstance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ajax&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;fetch&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>The names <code>&#39;backingStore&#39;</code>, <code>&#39;json&#39;</code>, <code>&#39;webApi&#39;</code> and <code>&#39;fetch&#39;</code> resolve to the defaults; <code>&#39;fetch&#39;</code> gives an ajax adapter that sends requests through <code>config.fetch</code>. A name that is neither registered nor a default still throws <code>Unregistered adapter</code>.</p><p>A custom adapter still has to be registered, by your own code or with <code>configureBreeze({ dataService: MyAdapter })</code>. Do it at startup, before you create an <code>EntityManager</code> — see <a href="/breeze-client-v3/guide/configuration#adapters-and-transport">Default adapters</a>.</p><h2 id="_4-you-no-longer-need-an-ajax-adapter" tabindex="-1">4. You no longer need an ajax adapter <a class="header-anchor" href="#_4-you-no-longer-need-an-ajax-adapter" aria-label="Permalink to &quot;4. You no longer need an ajax adapter&quot;">​</a></h2><p>Breeze 3 makes every request through a <code>fetch</code> function — <code>globalThis.fetch</code> unless you supply your own — so a normal setup has no ajax adapter:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">configureBreeze</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ fetch: myFetch });   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// optional: auth headers, retry, logging</span></span></code></pre></div><p>You don&#39;t have to change anything. <code>AjaxFetchAdapter</code>, <code>configureBreeze({ ajax })</code>, <code>config.initializeAdapterInstance(&#39;ajax&#39;, &#39;fetch&#39;)</code> and the adapter&#39;s <code>defaultSettings</code> and <code>requestInterceptor</code> all still work, and a registered ajax adapter is used in preference to <code>config.fetch</code>. They are deprecated: move to a <code>fetch</code> function when convenient — see <a href="/breeze-client-v3/server/transport">Supplying your own transport</a>.</p><p>A custom ajax adapter still works the same way. So does a data service adapter that calls <code>this.ajaxImpl.ajax(...)</code> directly; <code>_ajax()</code> is the promise-based alternative.</p><p><code>AbstractDataServiceAdapter</code> is promise-based: <code>fetchMetadata</code>, <code>executeQuery</code> and <code>saveChanges</code> are <code>async</code> and return native promises, sharing one <code>_ajax</code> helper. A 2.x subclass that overrode only <code>_prepareSaveBundle</code>, <code>_prepareSaveResult</code> and <code>jsonResultsAdapter</code> works unchanged. An override that returned a Q promise must return a native one.</p><p>A side effect: registration order no longer matters. In 2.x the data service adapter needed the ajax adapter registered first, and threw <code>Unable to find ajax adapter for dataservice adapter &#39;webApi&#39;</code> otherwise.</p><h2 id="_5-class-constructors-require-new" tabindex="-1">5. Class constructors require <code>new</code> <a class="header-anchor" href="#_5-class-constructors-require-new" aria-label="Permalink to &quot;5. Class constructors require \`new\`&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Predicate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CompanyName&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;StartsWith&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;B&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 2.x: worked. v3: throws.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Predicate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CompanyName&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;StartsWith&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;B&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// works</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Predicate.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">create</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CompanyName&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;startsWith&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;B&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// works, preferred</span></span></code></pre></div><p>v3 ships real ES2022 classes, and a class constructor cannot be invoked as a plain function. In 2.x this appeared to work only because the <em>test harness</em> compiled the library down to ES5; anyone consuming the <code>mjs</code> build was already affected.</p><p>Fix by adding <code>new</code>, or using the static factory where one exists.</p><h2 id="_6-the-default-naming-convention-is-now-camelcase" tabindex="-1">6. The default naming convention is now <code>camelCase</code> <a class="header-anchor" href="#_6-the-default-naming-convention-is-now-camelcase" aria-label="Permalink to &quot;6. The default naming convention is now \`camelCase\`&quot;">​</a></h2><p><strong>Breaking change.</strong> In 2.x the default was <code>NamingConvention.none</code>: client property names were the server&#39;s names unless you set a convention. Breeze 3 defaults to <code>NamingConvention.camelCase</code>, which suits a Breeze .NET server: <code>CompanyName</code> on the server is <code>companyName</code> on the client. A <code>MetadataStore</code> takes the default when it is created, so every store, and every <code>EntityManager</code> that creates its own, uses camelCase unless told otherwise. With the default adapters, a Breeze .NET server needs no configuration at all:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { EntityManager } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;breeze-client&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> em</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> EntityManager</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/breeze/Northwind&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><ul><li><p><strong>If you already set camelCase</strong>, nothing changes. <code>NamingConvention.camelCase.setAsDefault()</code> or <code>configureBreeze({ namingConvention: NamingConvention.camelCase })</code> is now redundant but harmless; you can delete it.</p></li><li><p><strong>If you relied on <code>none</code></strong> — your server already sends the property names the client should use, as a Node/Sequelize-style server does, or its metadata names are already camelCase — set it explicitly at startup, before you create any <code>MetadataStore</code> or <code>EntityManager</code>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { configureBreeze, NamingConvention } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;breeze-client&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">configureBreeze</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ namingConvention: NamingConvention.none });</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// or: NamingConvention.none.setAsDefault();</span></span></code></pre></div><p>Without it, PascalCase server names reach your code camel-cased, so code that reads <code>CompanyName</code> finds nothing. Server names that are already camelCase do not round-trip (<code>camelCase</code> turns <code>companyName</code> back into <code>CompanyName</code>), so metadata either fails to load with a <code>does not roundtrip properly</code> error, or Breeze sends the server upper-cased names.</p></li></ul><p>Metadata that names a naming convention still sets it when imported into an empty store, so a store loaded from an <code>exportMetadata()</code> file keeps the convention it was exported with. <code>NamingConvention.none</code> appears there as <code>&#39;noChange&#39;</code>. See <a href="/breeze-client-v3/server/namingconvention">Naming conventions</a>.</p><p><code>configureBreeze</code> takes <code>namingConvention</code> directly. There is no <code>breeze.</code> global, and no <code>NamingConvention.instance</code> — the current default is <code>NamingConvention.defaultInstance</code>.</p><h2 id="_7-typed-configuration-optional-recommended" tabindex="-1">7. Typed configuration (optional, recommended) <a class="header-anchor" href="#_7-typed-configuration-optional-recommended" aria-label="Permalink to &quot;7. Typed configuration (optional, recommended)&quot;">​</a></h2><p>For the standard adapters you need neither form: they are the defaults. When you do register an adapter of your own, <code>configureBreeze</code> replaces the stringly-typed pairs:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// still works, now deprecated</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">registerAdapter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;dataService&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, MyWebApiAdapter);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">initializeAdapterInstance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;dataService&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;myWebApi&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// preferred</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">configureBreeze</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ dataService: MyWebApiAdapter });</span></span></code></pre></div><p>Misspell an adapter name in the old form and you get a runtime error; in the new form it does not compile. The old API is not scheduled for removal. <code>configureBreeze</code> itself is optional: use it for a custom adapter, a custom <code>fetch</code>, or the naming convention.</p><p>If you call <code>config.initializeAdapterInstances</code> from TypeScript, you can drop any cast: its argument is now typed as adapter names, <code>{ ajax: &#39;fetch&#39;, dataService: &#39;webApi&#39; }</code>.</p><h3 id="noeval-is-removed-and-breeze-no-longer-evaluates-strings" tabindex="-1"><code>noEval</code> is removed, and Breeze no longer evaluates strings <a class="header-anchor" href="#noeval-is-removed-and-breeze-no-longer-evaluates-strings" aria-label="Permalink to &quot;\`noEval\` is removed, and Breeze no longer evaluates strings&quot;">​</a></h3><p><code>config.noEval</code> and <code>configureBreeze({ noEval })</code> are gone. Remove them — passing <code>noEval</code> to <code>configureBreeze</code> is a compile error, and <code>config.noEval</code> reads as <code>undefined</code>.</p><p>Nothing replaces them, because there is nothing left to switch off. The flag existed because 2.x built entity constructors from strings, <code>Function(&#39;return function Order(){}&#39;)()</code>, so a type had a readable name in a debugger — and probed for that ability at startup with <code>Function(&#39;&#39;)</code> inside a <code>try</code>, which a strict Content Security Policy reports as a violation even though the failure was caught.</p><p>Constructors are now named with <code>Object.defineProperty</code>, which gives the same result with no dynamic code. Breeze contains no <code>eval</code> and no <code>new Function</code>, so it runs under a policy without <code>&#39;unsafe-eval&#39;</code> and reports nothing at startup.</p><h2 id="_8-types-are-stricter" tabindex="-1">8. Types are stricter <a class="header-anchor" href="#_8-types-are-stricter" aria-label="Permalink to &quot;8. Types are stricter&quot;">​</a></h2><p>v3 builds under <code>strictNullChecks</code> and <code>noImplicitAny</code>. Two declarations changed in ways you may notice:</p><ul><li><code>getProperty</code> and <code>setProperty</code> are <strong>no longer optional</strong>, on <code>Entity</code> or on <code>ComplexObject</code>. They never were in practice — the model library adapter installs them on every entity — and marking them optional forced needless null checks on callers. Drop the <code>!</code> or <code>?.</code> you may have needed. A class that <code>implements Entity</code> now has to list them, with <code>declare</code> so the field does not shadow what Breeze installs — see <a href="/breeze-client-v3/guide/extending-entities#class-fields-and-declare">Class fields and <code>declare</code></a>.</li><li><code>EntityQuery.wherePredicate</code>, <code>EntityAspect.hasTempKey</code> and <code>ValidationError.propertyName</code> are now optional, which is what they always were at runtime.</li></ul><p>These are type-only changes; nothing behaves differently.</p><h2 id="_9-the-callback-arguments-are-deprecated" tabindex="-1">9. The callback arguments are deprecated <a class="header-anchor" href="#_9-the-callback-arguments-are-deprecated" aria-label="Permalink to &quot;9. The callback arguments are deprecated&quot;">​</a></h2><p>The async methods have always taken an optional success and failure callback alongside the promise they return. That pair is now deprecated on <code>EntityManager.executeQuery</code>, <code>saveChanges</code> and <code>fetchMetadata</code>, <code>EntityQuery.execute</code>, <code>EntityAspect.loadNavigationProperty</code>, <code>MetadataStore.fetchMetadata</code> and a relation array&#39;s <code>load</code>.</p><p>Nothing has stopped working, and none of these calls change behaviour. Your editor will strike the call through, and the callbacks will be removed in a future major version:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// deprecated</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">em.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">executeQuery</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(query, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">data</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> render</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(data.results), </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">err</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> show</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(err));</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// supported</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">try</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> data</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> em.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">executeQuery</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(query);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  render</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(data.results);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">catch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (err) {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  show</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(err);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The promise form is the only one that was ever fully supported: the save-queuing mixin, for instance, has always ignored the callback arguments.</p><p>The callback types — <code>Callback</code>, <code>ErrorCallback</code>, <code>QuerySuccessCallback</code> and <code>QueryErrorCallback</code> — are deprecated along with them.</p><h2 id="_10-promises-are-native" tabindex="-1">10. Promises are native <a class="header-anchor" href="#_10-promises-are-native" aria-label="Permalink to &quot;10. Promises are native&quot;">​</a></h2><p>Every async method returns a native <code>Promise</code>. Use <code>await</code>, or <code>.then</code>/<code>.catch</code>. The Q idiom that 2.x code often used does not exist:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">em.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">saveChanges</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fail</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(handler);    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 2.x with Q — TypeError in v3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">em.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">saveChanges</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(handler);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// v3</span></span></code></pre></div><p>Nothing else in the query or save contract changed.</p><h2 id="_11-save-errors-arrive-as-a-problem-details-document" tabindex="-1">11. Save errors arrive as a problem details document <a class="header-anchor" href="#_11-save-errors-arrive-as-a-problem-details-document" aria-label="Permalink to &quot;11. Save errors arrive as a problem details document&quot;">​</a></h2><p>A Breeze .NET server now returns <a href="https://www.rfc-editor.org/rfc/rfc9457" target="_blank" rel="noreferrer">RFC 9457</a><code>application/problem+json</code>, with <code>type</code>, <code>title</code>, <code>status</code> and <code>detail</code>. Before 3.0 it sent <code>{ Code, Message, StackTrace, EntityErrors }</code> with no content type of its own, always included the stack trace, and set <code>Code</code> to <code>0</code> for anything that was not an <code>EntityErrorsException</code>.</p><p><strong>A client needs no changes.</strong> Breeze reads either spelling, <code>e.message</code> comes from <code>detail</code> falling back to <code>title</code>, and the capitalised members are still sent by default so an application on an older client reads the error unchanged. It matters only if you parse the response yourself. See <a href="/breeze-client-v3/guide/error-handling#what-the-server-sends">Error handling</a>.</p><h2 id="what-has-not-changed" tabindex="-1">What has not changed <a class="header-anchor" href="#what-has-not-changed" aria-label="Permalink to &quot;What has not changed&quot;">​</a></h2><p>The rest of the API is intended to be source-compatible. <code>EntityManager</code>, <code>EntityQuery</code>, <code>Predicate</code>, <code>MetadataStore</code>, <code>EntityType</code>, <code>EntityAspect</code>, <code>Validator</code>, <code>DataType</code>, the <code>BreezeEnum</code> types, save and query options, and the event model all keep their names, shapes and semantics.</p><p>If you hit a difference not listed here, it is a bug — please <a href="https://github.com/Breeze/breeze-client-v3/issues" target="_blank" rel="noreferrer">file an issue</a>.</p><h2 id="still-there-just-not-in-the-api-reference" tabindex="-1">Still there, just not in the API reference <a class="header-anchor" href="#still-there-just-not-in-the-api-reference" aria-label="Permalink to &quot;Still there, just not in the API reference&quot;">​</a></h2><p>The reference documents the surface an application uses. Two dozen exported names carry <code>@hidden</code>, which keeps a declaration out of the reference but not out of the package: they are in the published <code>.d.ts</code>, they compile, and they run. <strong>Every one of them was <code>@hidden</code> in 2.x too</strong> — nothing was hidden in 3.0. They are listed here because the natural way to check whether something survived the upgrade is to search the reference for it, and these are the names that are present but will not be found.</p><p>For writing an adapter — you need these only if you implement one:</p><table tabindex="0"><thead><tr><th>For</th><th>Names</th></tr></thead><tbody><tr><td>a <code>DataServiceAdapter</code></td><td><code>AbstractDataServiceAdapter</code>, <code>MappingContext</code>, <code>SaveContext</code>, <code>SaveBundle</code></td></tr><tr><td>a <code>UriBuilderAdapter</code></td><td><code>OrderByClause</code>, <code>SelectClause</code>, <code>ExpandClause</code></td></tr><tr><td>a <code>ModelLibraryAdapter</code></td><td><code>makeRelationArray</code>, <code>makePrimitiveArray</code>, <code>makeComplexArray</code></td></tr><tr><td>registering either</td><td><code>AdapterCtor</code>, <code>AdapterRegistration</code></td></tr></tbody></table><p>For walking a predicate with <code>Predicate.visit</code>: the tree nodes <code>UnaryPredicate</code>, <code>BinaryPredicate</code>, <code>AndOrPredicate</code>, <code>AnyAllPredicate</code>, <code>LitExpr</code>, <code>FnExpr</code> and <code>PropExpr</code>, and the <code>Visitor</code>, <code>VisitContext</code> and <code>ExpressionContext</code> types a visitor is written against.</p><h3 id="assertparam-and-assertconfig-went-the-other-way" tabindex="-1"><code>assertParam</code> and <code>assertConfig</code> went the other way <a class="header-anchor" href="#assertparam-and-assertconfig-went-the-other-way" aria-label="Permalink to &quot;\`assertParam\` and \`assertConfig\` went the other way&quot;">​</a></h3><p>They are <em>more</em> available than in 2.x, not less. 2.x marked them <code>@hidden @internal</code>, and <code>@internal</code> strips a declaration from the published <code>.d.ts</code> — so although the runtime export was there, TypeScript could not see it. In 3.0 they are <code>@hidden</code> only: still out of the reference, but exported by name from <code>breeze-client</code> and typed. <code>Param</code> itself stays off the barrel; reach it as <code>breeze.Param</code>, which is typed, or let <code>assertParam</code> build one.</p><h3 id="five-core-members-that-exist-only-at-runtime" tabindex="-1">Five <code>core</code> members that exist only at runtime <a class="header-anchor" href="#five-core-members-that-exist-only-at-runtime" aria-label="Permalink to &quot;Five \`core\` members that exist only at runtime&quot;">​</a></h3><p><code>assert-param.ts</code>, <code>config.ts</code> and <code>event.ts</code> each assign a member onto <code>core</code> at import time, for 2.x code that reached them through the <code>breeze.core</code> global. They are not on the <code>core</code> type, in 3.0 or in 2.x, so TypeScript rejects all five even though the call works. Use the real export instead:</p><table tabindex="0"><thead><tr><th>At runtime only</th><th>Use instead</th></tr></thead><tbody><tr><td><code>core.assertParam</code>, <code>core.assertConfig</code></td><td>the exports of the same name</td></tr><tr><td><code>core.Param</code></td><td><code>breeze.Param</code></td></tr><tr><td><code>core.config</code></td><td>the exported <code>config</code></td></tr><tr><td><code>core.Event</code></td><td>the exported <code>BreezeEvent</code></td></tr></tbody></table><p>Two more pieces of 2.x scaffolding are still in place: <code>window.breeze</code>, set when the module runs unbundled, and the empty <code>promises.IPromiseService</code> that <code>breeze-bridge2-angular</code> imports.</p><p>One caveat carried over from 2.x unchanged: <code>breeze.assertParam</code> and <code>breeze.assertConfig</code> are <code>null</code>, not functions — the lines that would have assigned them are commented out in both versions. Call <code>assertParam</code> directly. <code>breeze.version</code> is likewise still the 2.x string.</p><h2 id="fixed-along-the-way" tabindex="-1">Fixed along the way <a class="header-anchor" href="#fixed-along-the-way" aria-label="Permalink to &quot;Fixed along the way&quot;">​</a></h2><p>Long-standing defects, all present in 2.x:</p><ul><li><strong><code>JsonResultsAdapter</code> lost its type brand.</strong> It declared <code>_$typeName</code> without TypeScript&#39;s <code>declare</code> modifier, so under ES2022 class-field semantics the constructor overwrote the prototype value with <code>undefined</code>, and <code>EntityQuery.using(myJsonResultsAdapter)</code> failed to recognise its argument.</li><li><strong>The fetch adapter set <code>referrer: &#39;client&#39;</code></strong>, which is the browser default and redundant there, but which Node&#39;s <code>fetch</code> rejects outright — making Breeze unusable with the fetch adapter under Node.</li><li><strong><code>config.initializeAdapterInstances</code> always threw.</strong> It validated its argument, copied it onto the global <code>config</code>, and then iterated every property of <code>config</code> rather than of the argument — passing values such as <code>functionRegistry</code> to <code>initializeAdapterInstance</code> as adapter names. Nothing tested it. It now initializes exactly the adapters named, in dependency order, and leaves <code>config</code> alone.</li><li><strong>More types are exported.</strong> The config objects public constructors take (<code>EntityTypeConfig</code>, <code>QueryOptionsConfig</code>, <code>SaveOptionsConfig</code>, …), event args, callbacks, <code>SaveError</code>, <code>ImportResult</code> and the types adapter authors implement against were used in public signatures but could not be imported by name. They can now. Type-only; nothing changes at runtime.</li><li><strong>The fetch adapter could leave a query pending for ever.</strong> A 200 response whose body was not JSON (an HTML login page from a proxy, say) failed inside the adapter without reaching either callback. Every path now settles, and an unreadable body reports the real HTTP status. A throw inside a data service adapter callback now rejects the promise too.</li><li><strong>Calling <a href="/breeze-client-v3/guide/extensions#save-queuing"><code>enableSaveQueuing</code></a> twice hung <code>saveChanges</code></strong>, including turning it off with <code>enableSaveQueuing(em, false)</code>. It looked up a misspelled property, so each call wrapped <code>saveChanges</code> again.</li><li><strong>Save queuing sent temporary keys to the server.</strong> With the <a href="/breeze-client-v3/guide/extensions#save-queuing">save-queuing mixin</a>, a foreign key set while its parent row was still being inserted kept its temporary (negative) value in the follow-up save, because the fixup compared the type that <em>declares</em> the foreign key instead of the type it points at. Only a self-referencing key ever matched. Against SQL Server the queued save failed with a foreign key constraint violation.</li><li><strong><code>removeValidationError(validator)</code> removed nothing.</strong> It now removes every error that validator produced on the entity.</li><li><strong>An entity whose key was the string <code>__proto__</code> could not be found again.</strong> The cache&#39;s key index was a plain object, so writing that one key ran <code>Object.prototype</code>&#39;s inherited setter and stored nothing: the entity was attached, <code>getEntityByKey</code> returned <code>null</code>, a re-query added a second copy, and detaching it threw <em>internal error - entity cannot be found in group</em>.</li><li><strong>Working with many changed entities at once is no longer quadratic.</strong> <code>acceptChanges</code>, <code>rejectChanges</code> and <code>detachEntity</code> each asked the manager to work out afresh whether anything was still dirty, which meant walking the whole cache — once per entity. Over 40,000 entities <code>acceptChanges</code> took 8.5 seconds; it takes 33 ms. <a href="/breeze-client-v3/guide/extensions#entity-graphs"><code>getEntityGraph</code></a> with a two-level expand was the same shape: 5.1 seconds over 8,000 orders and their 24,000 details, now 10 ms. See <a href="/breeze-client-v3/guide/performance#cache-operations-scale-with-what-you-touch-not-with-what-is-cached">Performance</a>.</li><li><strong><code>BreezeEvent.isEnabled</code> ignored its object argument</strong>, and <strong><code>EntityState.isDeletedOrDetached()</code> returned false for <code>Deleted</code>.</strong></li><li><strong>Local projections named nested paths differently from the server.</strong> Only the first dot was replaced, and the client names were used: <code>order.customer.companyName</code> came back as <code>order_customer.companyName</code>. A local projection now uses the name the server gives the path, passed through the naming convention, so it matches a remote one: <code>order_Customer_CompanyName</code> with camelCase. See <a href="/breeze-client-v3/query/projections#related-property-projections">Projections</a>.</li><li><strong>A string assigned to a <code>DateOnly</code> property stayed a string.</strong> It is now parsed as a local date.</li><li><strong><code>config.getAdapterInstance</code> was missing from the published type declarations.</strong> It was tagged <code>@internal</code> and the build strips internal members, so TypeScript code calling it needed a cast. It is now public.</li></ul><h3 id="fixes-that-change-what-your-code-sees" tabindex="-1">Fixes that change what your code sees <a class="header-anchor" href="#fixes-that-change-what-your-code-sees" aria-label="Permalink to &quot;Fixes that change what your code sees&quot;">​</a></h3><p>These correct long-standing defects, but code that worked around them, or relied on them, may notice.</p><p><strong>Queries</strong></p><ul><li><strong>Local <code>substring</code> takes a length</strong>, as the server does: <code>substring(s, start, length)</code>. It used JavaScript&#39;s <code>substring(start, end)</code>, so a cache query could return different rows from the same query on the server.</li><li><strong><code>{ value, isLiteral: false }</code> in a where clause</strong> now makes the value a property expression, as documented. It was ignored.</li><li><strong><code>withParameters</code> values are sent once</strong>, as plain query-string arguments — the copy the .NET server reads. They used to be sent inside the JSON query as well; a query with only parameters now requests <code>Resource?name=value</code> with no JSON.</li><li><strong>Untyped results fall back to the resource&#39;s entity type.</strong> When a query&#39;s resource maps to an entity type, result nodes the JSON results adapter cannot type (no <code>$type</code>) now become entities of that type instead of plain objects. The fallback was computed and then dropped. Typed nodes, projections and <code>toType()</code> queries are unaffected.</li><li><strong><code>FilterQueryOp.IsTypeOf</code> is removed.</strong> The server has no such operator, so it could never work; code that referenced it now fails to compile instead of throwing at runtime.</li><li><code>EntityQuery.toJSON()</code> now includes <code>usePost</code>.</li></ul><p><strong><code>breeze.core</code> utilities</strong></p><ul><li><p><strong>Five <code>core</code> helpers are removed</strong>, all written for a JavaScript that no longer needs them and none of them used by Breeze itself any more. If you call one, the replacement is a built-in:</p><table tabindex="0"><thead><tr><th>Removed</th><th>Instead</th></tr></thead><tbody><tr><td><code>core.requireLib</code></td><td>Nothing. It found jQuery, Knockout or the OData client through browser globals or AMD <code>require</code>, and all four are gone from v3. Use an <code>import</code>.</td></tr><tr><td><code>core.isES5Supported</code></td><td>Nothing — it always answered <code>true</code>.</td></tr><tr><td><code>core.isNumeric(n)</code></td><td><code>Number.isFinite(Number(n))</code></td></tr><tr><td><code>core.titleCase(s)</code></td><td>Your own, or a library — it was one regex.</td></tr><tr><td><code>core.getArray(obj, name)</code></td><td><code>core.getMapArray(map, key)</code>, or <code>obj[name] ??= []</code></td></tr></tbody></table></li><li><p><strong>Six <code>core</code> helpers are deprecated</strong>, because the language now has each of them. They still work, and an editor will strike them through:</p><table tabindex="0"><thead><tr><th>Deprecated</th><th>Instead</th></tr></thead><tbody><tr><td><code>core.hasOwnProperty(obj, key)</code></td><td><code>Object.hasOwn(obj, key)</code></td></tr><tr><td><code>core.arraySlice(arr, start, end)</code></td><td><code>arr.slice(start, end)</code></td></tr><tr><td><code>core.arrayFlatMap(arr, fn)</code></td><td><code>arr.flatMap(fn)</code></td></tr><tr><td><code>core.getUuid()</code></td><td><code>crypto.randomUUID()</code></td></tr><tr><td><code>core.stringStartsWith(s, prefix)</code></td><td><code>s.startsWith(prefix)</code></td></tr><tr><td><code>core.stringEndsWith(s, suffix)</code></td><td><code>s.endsWith(suffix)</code></td></tr></tbody></table><p>Each now calls the built-in, so behaviour is unchanged and two of them are faster — <code>endsWith</code> by 2.3x, <code>getUuid</code> by about 30x, which is worth a few percent of creating an entity with a Guid key. <code>crypto.randomUUID()</code> is also a cryptographic source where the old implementation used <code>Math.random()</code>.</p><p>Two things to know before you switch:</p><ul><li><strong>The string helpers are null-tolerant and the built-ins are not.</strong><code>core.stringStartsWith(null, &quot;a&quot;)</code> is <code>false</code>, where <code>null.startsWith(&quot;a&quot;)</code> throws; and <code>core.stringStartsWith(&quot;abc&quot;, null)</code> is <code>true</code>, where the built-in looks for the text <code>&quot;null&quot;</code>. Guard the null yourself.</li><li><strong><code>crypto.randomUUID()</code> needs a secure context in a browser</strong> — it is unavailable over plain HTTP. <code>core.getUuid()</code> falls back to the old implementation there, so if you serve over HTTP, keep using it or supply your own fallback.</li></ul><p>An <code>Object.create</code> polyfill went with the five removals, so importing Breeze no longer writes to a global. Everything else <code>core</code> exposes is unchanged.</p></li></ul><p><strong>Metadata and data types</strong></p><ul><li><strong>More server type names are understood.</strong> <code>TimeSpan</code> maps to <code>DataType.Time</code>, <code>TimeOnly</code> to the new <code>DataType.TimeOnly</code> (a <code>&quot;HH:mm:ss&quot;</code> string), <code>Char</code> to <code>String</code>, and <code>SByte</code> and the unsigned integers to the next wider integer type. They all used to become <code>String</code> silently. A name the client still does not know imports as <code>DataType.Undefined</code>, with the original in <code>rawTypeName</code>, and logs a warning.</li><li><strong><code>DateOnly</code></strong> has the date validator, and sorts correctly across the year 2000.</li><li><strong>Comparison options you choose win.</strong> <code>localQueryComparisonOptions</code> named in imported metadata no longer override options passed to the <code>MetadataStore</code> or set with <code>setAsDefault()</code>. <code>LocalQueryComparisonOptions</code> no longer requires <code>usesSql92CompliantStringComparison</code> (default <code>true</code>).</li><li><strong><code>new EntityManager({ serviceName, metadataStore })</code> uses the store&#39;s <code>DataService</code></strong> for that service, with its <code>hasServerMetadata</code> and adapters, instead of building a new one.</li><li><code>importMetadata</code> for a new type with no <code>dataProperties</code> throws a clear error instead of a <code>TypeError</code>.</li></ul><p><strong>Validation</strong></p><ul><li><strong>An error you add with <code>addValidationError</code> now stops a save.</strong> <code>validateEntity()</code> returned <code>true</code> while one stood, and <code>saveChanges</code> sent the entity anyway; <code>validateProperty()</code> ignored one about its property. All three now treat it as an error until you remove it. Errors from the server still do not stop a save — every save clears them first. If you added errors as <em>warnings</em> that were not meant to block, remove them before saving, or keep warnings somewhere other than the entity&#39;s validation errors. See <a href="/breeze-client-v3/guide/validation#which-errors-stop-a-save">Which errors stop a save</a>.</li><li><strong>A save stopped by an added error beside an ordinary validation failure threw a <code>TypeError</code></strong> — <code>Cannot read properties of undefined (reading &#39;name&#39;)</code> — in place of the validation error and its <code>entityErrors</code>. It now rejects properly, naming the added error by its key in <code>errorName</code>.</li><li><strong>A server validation error goes when the property it is about is edited</strong>, instead of staying until the next save.</li><li><code>getValidationErrors(&#39;someProperty&#39;)</code> includes an error added with only a <code>propertyName</code> in its context, which it used to leave out.</li></ul><p><strong>Errors and adapters</strong></p><ul><li><strong>A failed request&#39;s <code>ServerError</code> now carries <code>statusText</code>, <code>body</code> and <code>url</code></strong>, which it always declared. A status-0 failure&#39;s message now says the server may not be running, and keeps the underlying message.</li><li>A save whose response has no body rejects with a clear error instead of a <code>TypeError</code>.</li><li>A failed query no longer <em>also</em> raises an unhandled promise rejection.</li><li><code>ChangeRequestInterceptor.oneTime</code> is honoured.</li><li>The <code>interfaceInitialized</code> event reports the real <code>isDefault</code>.</li></ul><p><strong>Types</strong></p><ul><li><code>EntityManagerConfig.keyGenerator</code> is removed. It was always rejected at runtime; use <code>keyGeneratorCtor</code>.</li><li><code>setProperty</code> is typed to return a value, so chaining compiles.</li><li><code>JsonResultsAdapterConfig.visitNode</code> is required in the type, as it always was at runtime.</li><li>Published for adapter authors: the static <code>AbstractDataServiceAdapter.makeHttpError</code> and the protected <code>_createChangeRequestInterceptor</code>.</li><li><code>DataService.useJsonp</code> is deprecated. It has no effect on Breeze’s own transport, which has no JSONP support; a registered (deprecated) ajax adapter can still act on it.</li></ul>`,108)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
